import "math/bits"

// Popcount returns the number of set bits across all words of xs.
func Popcount(xs []uint64) int {
	n := 0
	i := 0
	for ; i+16 <= len(xs); i += 16 {
		_ = xs[i+15]
		n += bits.OnesCount64(xs[i]) + bits.OnesCount64(xs[i+1]) +
			bits.OnesCount64(xs[i+2]) + bits.OnesCount64(xs[i+3]) +
			bits.OnesCount64(xs[i+4]) + bits.OnesCount64(xs[i+5]) +
			bits.OnesCount64(xs[i+6]) + bits.OnesCount64(xs[i+7]) +
			bits.OnesCount64(xs[i+8]) + bits.OnesCount64(xs[i+9]) +
			bits.OnesCount64(xs[i+10]) + bits.OnesCount64(xs[i+11]) +
			bits.OnesCount64(xs[i+12]) + bits.OnesCount64(xs[i+13]) +
			bits.OnesCount64(xs[i+14]) + bits.OnesCount64(xs[i+15])
	}
	for ; i < len(xs); i++ {
		n += bits.OnesCount64(xs[i])
	}
	return n
}

